// Helper to render a testimonial card
function sh_render_testi_card($c, $filter_labels) {
    $plat = esc_attr($c['platform']);
    $badge = isset($filter_labels[$c['platform']]) ? $filter_labels[$c['platform']] : strtoupper(substr($c['platform'], 0, 2));
    $stars = isset($c['stars']) ? (int) $c['stars'] : 5;
    $star_filled = '<svg width="13" height="13" viewBox="0 0 24 24" fill="var(--glow,#f6f5f2)" stroke="var(--glow,#f6f5f2)" stroke-width="1.2" style="display:block"><path d="m12 2 3 6.5 7 .7-5.2 4.7 1.5 6.9L12 17.8 5.2 20.8l1.5-6.9L1.5 9.2l7-.7z"></path></svg>';
