    ?>
<div data-testi-card="true" data-plat="<?php echo $plat; ?>" style="border:1px solid rgba(255,255,255,.1);border-radius:18px;background:linear-gradient(155deg,rgba(255,255,255,.05),rgba(255,255,255,.02));backdrop-filter:blur(18px) saturate(140%);-webkit-backdrop-filter:blur(18px) saturate(140%);box-shadow:inset 0 1px 0 rgba(255,255,255,.16),0 24px 50px rgba(0,0,0,.42);padding:14px;margin-bottom:14px;transform-style:preserve-3d;transition:transform .3s var(--ease-brand,cubic-bezier(.22,.61,.36,1)),box-shadow .3s,opacity .3s;will-change:transform">
<?php if (!empty($c['yt'])) : ?>
<div style="position:relative;width:100%;aspect-ratio:16/9;border-radius:10px;overflow:hidden;margin-bottom:10px"><?php if (!empty($c['avatar_url'])) : ?><img src="<?php echo esc_url($c['avatar_url']); ?>" alt="" loading="lazy" style="width:100%;height:100%;object-fit:cover;display:block"><?php endif; ?><div style="position:absolute;inset:0;background:rgba(3,4,5,.32)"></div><button data-testi-play="true" data-yt="<?php echo esc_attr($c['yt']); ?>" type="button" aria-label="Play review" style="position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:48px;height:48px;display:flex;align-items:center;justify-content:center;padding:0;border:1px solid var(--glow,#f6f5f2);border-radius:999px;background:rgba(3,4,5,.4);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);cursor:pointer;pointer-events:auto"><svg width="18" height="18" viewBox="0 0 24 24" fill="var(--glow,#f6f5f2)"><path d="M8 5v14l11-7z"></path></svg></button></div>
<?php endif; ?>
<div style="display:flex;gap:3px;margin-bottom:9px"><?php for ($s = 0; $s < 5; $s++) echo ($s < $stars) ? $star_filled : $star_empty; ?></div>
<p style="margin:0 0 11px;font-family:var(--font-body,sans-serif);font-weight:400;font-size:13px;line-height:1.5;color:var(--tx,#f4f4f5)"><?php echo esc_html($c['text']); ?></p>
<div style="display:flex;align-items:center;gap:12px">
